SELECT EXPORT_FLAG   AS exportFlag
      ,SM.INVOICE_DATE AS invoiceDate
      ,VIRTUAL_YN    AS virtualYn
FROM   SALES_MST SM
WHERE  SALES_NO = #{salesNo}
AND    SM.DIVISION_CODE = #{divisionCode}
AND    SM.COMPANY_CODE = #{companyCode}

SELECT COUNT(*)
FROM   FCR_MST
WHERE  SALES_NO = #{salesNo}
AND    DIVISION_CODE = #{divisionCode}
AND    COMPANY_CODE = #{companyCode}
AND    IM_APPLY_YN = 'MF'

SELECT SALES_SEQ          AS salesSeq
      ,PRODUCT_CODE       AS productCode
      ,PROD_DIVISION_CODE AS prodDivisionCode
      ,STATUS             AS status
FROM   SALES_DTL
WHERE  SALES_NO = #{salesNo}
AND    DIVISION_CODE = #{divisionCode}
AND    COMPANY_CODE = #{companyCode}
AND    PRODUCT_ASSETS_TYPE IN ('P', 'H')

AND    PRODUCT_CODE IN

           #{productCode}

SELECT DIVISION_CODE AS divisionCode
      ,FBD.YYYYMM    AS yyyymm
FROM   FTA_BOM_DTL FBD
WHERE  FBD.COMPANY_CODE = #{companyCode}
AND    FBD.DIVISION_CODE = #{prodDivisionCode}
AND    FBD.PRODUCT_CODE = #{productCode}
AND    FBD.TXN_TYPE = #{bomType}
AND    FBD.REQ_QTY >= 0
AND    FBD.YYYYMM = (SELECT MAX(FBDT.YYYYMM)
                      FROM   FTA_BOM_DTL FBDT
                      WHERE  FBDT.COMPANY_CODE = #{companyCode}
                      AND    FBDT.DIVISION_CODE = #{prodDivisionCode}
                      AND    FBDT.PRODUCT_CODE = #{productCode}
                      AND    FBDT.TXN_TYPE = #{bomType}
                      AND    FBDT.YYYYMM BETWEEN #{bomPreviousYyyymm} AND #{yyyymm})
FETCH FIRST 1 ROW ONLY

SELECT DIVISION_CODE AS divisionCode
      ,FBD.YYYYMM    AS yyyymm
FROM   FTA_BOM_DTL FBD
WHERE  FBD.COMPANY_CODE = #{companyCode}
AND    FBD.PRODUCT_CODE = #{productCode}
AND    FBD.TXN_TYPE = #{bomType}
AND    FBD.REQ_QTY >= 0
AND    FBD.YYYYMM = (SELECT MAX(FBDT.YYYYMM)
                      FROM   FTA_BOM_DTL FBDT
                      WHERE  FBDT.COMPANY_CODE = #{companyCode}
                      AND    FBDT.PRODUCT_CODE = #{productCode}
                      AND    FBDT.TXN_TYPE = #{bomType}
                      AND    FBDT.YYYYMM BETWEEN #{bomPreviousYyyymm} AND #{yyyymm})
FETCH FIRST 1 ROW ONLY

mapper.update:
UPDATE SALES_DTL
SET    STATUS            = #{status}
      ,BOM_STATUS        = #{bomStatus}
      ,BOM_YYYYMM        = #{bomYyyymm}
      ,BOM_DIVISION_CODE = #{bomDivisionCode}
      ,UPDATE_DATE       = CURRENT_TIMESTAMP
WHERE  SALES_NO = #{salesNo}
AND    SALES_SEQ = #{salesSeq}
AND    DIVISION_CODE = #{divisionCode}
AND    COMPANY_CODE = #{companyCode}
AND    PRODUCT_CODE = #{productCode}

