mapper.select:
SELECT SM.SALES_NO AS salesNo ,SD.SALES_SEQ AS salesSeq ,SD.PRODUCT_CODE AS productCode ,SD.DIVISION_CODE AS divisionCode ,SM.COMPANY_CODE AS companyCode ,SD.STANDARD AS standard ,(SD.AMOUNT / SD.QUANTITY) AS amount ,COALESCE(SD.SP_COO_YN, 'N') AS spCooYn ,CASE WHEN SD.PRODUCT_ASSETS_TYPE = 'B' THEN 'Y' ELSE 'N' END AS woCooYn ,SD.PRODUCT_UNIT AS productUnit ,SD.PRODUCT_ASSETS_TYPE AS productAssetsType ,SD.PROD_DIVISION_CODE AS prodDivisionCode ,SM.INVOICE_DATE AS invoiceDate ,SM.EXPORT_FLAG AS exportFlag ,SD.DELIVERY_CUSTOMER_CODE AS deliveryCustomerCode ,SM.ARRIVAL_NATION AS arrivalNation FROM SALES_MST SM INNER JOIN SALES_DTL SD ON SM.SALES_NO = SD.SALES_NO AND SM.COMPANY_CODE = SD.COMPANY_CODE AND SM.DIVISION_CODE = SD.DIVISION_CODE WHERE SM.SALES_NO = #{salesNo} AND SM.DIVISION_CODE = #{divisionCode} AND SM.COMPANY_CODE = #{companyCode} AND SD.QUANTITY > 0 AND SD.BOM_STATUS <> '1'
AND SD.PRODUCT_CODE IN
#{productCode}

SELECT FM.FTA_CODE AS ftaCode ,SALES.SALES_NO AS salesNo ,SALES.SALES_SEQ AS salesSeq ,SALES.PRODUCT_CODE AS productCode ,SALES.DIVISION_CODE AS divisionCode ,SALES.COMPANY_CODE AS companyCode ,SALES.STANDARD AS standard ,SALES.QUANTITY AS quantity ,SALES.AMOUNT AS amount ,SALES.INKOTERMS AS inkoterms ,SALES.SP_COO_YN AS spCooYn ,SALES.WO_COO_YN AS woCooYn ,SALES.PRODUCT_UNIT AS productUnit ,SALES.PRODUCT_ASSETS_TYPE AS productAssetsType ,SALES.PROD_DIVISION_CODE AS prodDivisionCode ,SALES.EXPORT_FLAG AS exportFlag ,SALES.ARRIVAL_NATION AS arrivalNation ,SALES.INVOICE_DATE AS invoiceDate ,SALES.DELIVERY_CUSTOMER_CODE AS deliveryCustomerCode ,FM.INTERMEDIATE_YN AS intermediateYn FROM (SELECT SM.SALES_NO ,SD.SALES_SEQ ,SD.PRODUCT_CODE ,SD.DIVISION_CODE ,SD.COMPANY_CODE ,SD.STANDARD ,SD.QUANTITY ,(SD.AMOUNT / SD.QUANTITY) AS AMOUNT ,SM.INKOTERMS ,SM.TARGET_FTA_CODE AS TARGET_FTA_CODE ,COALESCE(SD.SP_COO_YN, 'N') AS SP_COO_YN ,CASE WHEN SD.PRODUCT_ASSETS_TYPE = 'B' THEN 'Y' ELSE 'N' END AS WO_COO_YN ,SD.PRODUCT_UNIT ,SD.PRODUCT_ASSETS_TYPE ,SD.PROD_DIVISION_CODE ,SM.EXPORT_FLAG ,COALESCE(SM.ARRIVAL_NATION, C.NATION_CODE) AS ARRIVAL_NATION ,SM.INVOICE_DATE ,SD.DELIVERY_CUSTOMER_CODE FROM SALES_MST SM INNER JOIN SALES_DTL SD ON SM.SALES_NO = SD.SALES_NO AND SM.DIVISION_CODE = SD.DIVISION_CODE AND SM.COMPANY_CODE = SD.COMPANY_CODE AND SD.BOM_STATUS <> '1' INNER JOIN CUSTOMER C ON SM.CUSTOMER_CODE = C.CUSTOMER_CODE AND SM.COMPANY_CODE = C.COMPANY_CODE WHERE SM.SALES_NO = #{salesNo} AND SM.DIVISION_CODE = #{divisionCode} AND SM.COMPANY_CODE = #{companyCode}
AND SD.PRODUCT_CODE IN
#{productCode}
) SALES INNER JOIN FTA_APPLY_NATION FAN ON FAN.NATION_CODE = SALES.ARRIVAL_NATION AND FAN.EFFECT_DATE <= SALES.INVOICE_DATE INNER JOIN FTA_MASTER FM ON FM.DELETE_YN = 'N' AND FM.FTA_CODE = SALES.TARGET_FTA_CODE AND FM.COMPANY_CODE = SALES.COMPANY_CODE AND FM.FTA_CODE = FAN.FTA_CODE AND FM.FTA_STATUS = '4'

SELECT FBD.ITEM_CODE AS itemCode ,FM.FTA_CODE AS ftaCode ,FM.SALES_NO AS salesNo ,FM.SALES_SEQ AS salesSeq ,FM.PRODUCT_CODE AS productCode ,FM.DIVISION_CODE AS divisionCode ,FM.COMPANY_CODE AS companyCode ,COALESCE(IM.HS_CODE, COALESCE(FM.HS_CODE, ' ')) AS hsCode ,IM.HS_CODE AS itemHsCode ,FBD.REQ_QTY * SD.UNIT_EXCHANGE_RATE AS requirementQty ,FBD.FROM_DIVISION_CODE AS fromDivisionCode FROM (SELECT SD.SALES_NO ,SD.SALES_SEQ ,SD.PRODUCT_CODE ,SD.DIVISION_CODE ,SD.COMPANY_CODE ,SD.BOM_STATUS ,SD.BOM_YYYYMM ,SD.BOM_DIVISION_CODE ,CAST(COALESCE(SD.ATTRIBUTE02, '1') AS DECIMAL) AS UNIT_EXCHANGE_RATE FROM SALES_DTL SD INNER JOIN SALES_MST SM ON SD.SALES_NO = SM.SALES_NO AND SD.DIVISION_CODE = SM.DIVISION_CODE AND SD.COMPANY_CODE = SM.COMPANY_CODE WHERE SD.SALES_NO = #{salesNo} AND SD.DIVISION_CODE = #{divisionCode} AND SD.COMPANY_CODE = #{companyCode} AND SD.BOM_STATUS <> '1'
AND SD.PRODUCT_CODE IN
#{productCode}
) SD INNER JOIN FCR_MST FM ON SD.SALES_NO = FM.SALES_NO AND SD.SALES_SEQ = FM.SALES_SEQ AND SD.DIVISION_CODE = FM.DIVISION_CODE AND SD.COMPANY_CODE = FM.COMPANY_CODE AND SD.PRODUCT_CODE = FM.PRODUCT_CODE INNER JOIN FTA_BOM_DTL FBD ON FBD.PRODUCT_CODE = SD.PRODUCT_CODE AND FBD.DIVISION_CODE = SD.BOM_DIVISION_CODE AND FBD.COMPANY_CODE = SD.COMPANY_CODE AND FBD.YYYYMM = SD.BOM_YYYYMM AND FBD.ISLEAF_YN = 'Y' INNER JOIN ITEM_MST IM ON FBD.ITEM_CODE = IM.ITEM_CODE AND FBD.COMPANY_CODE = IM.COMPANY_CODE AND IM.DELETE_YN = 'N' WHERE FM.PRODUCT_ASSETS_TYPE IN ('P', 'H') AND FBD.TXN_TYPE = #{bomType} AND FBD.REQ_QTY >= 0 AND NOT EXISTS (SELECT 1 FROM EXCEPT_ITEM E WHERE FBD.ITEM_CODE = E.ITEM_CODE AND FM.FTA_CODE = E.FTA_CODE AND E.COMPANY_CODE = #{companyCode})

SELECT FM.PRODUCT_CODE AS productCode ,FM.FTA_CODE AS ftaCode ,FM.SALES_NO AS salesNo ,FM.SALES_SEQ AS salesSeq ,FM.DIVISION_CODE AS divisionCode ,FM.COMPANY_CODE AS companyCode ,COALESCE(IM.HS_CODE, COALESCE(FM.HS_CODE, ' ')) AS hsCode ,FM.HS_CODE AS itemHsCode ,SD.UNIT_PRICE AS unitPrice ,SD.PRODUCT_ASSETS_TYPE AS productAssetsType ,SD.PROD_DIVISION_CODE AS prodDivisionCode FROM FCR_MST FM INNER JOIN SALES_DTL SD ON SD.SALES_NO = FM.SALES_NO AND SD.SALES_SEQ = FM.SALES_SEQ AND SD.DIVISION_CODE = FM.DIVISION_CODE AND SD.COMPANY_CODE = FM.COMPANY_CODE INNER JOIN SALES_MST SM ON SD.SALES_NO = SM.SALES_NO AND SD.DIVISION_CODE = SM.DIVISION_CODE AND SD.COMPANY_CODE = SM.COMPANY_CODE INNER JOIN ITEM_MST IM ON SD.PRODUCT_CODE = IM.ITEM_CODE AND SD.COMPANY_CODE = IM.COMPANY_CODE WHERE SD.SALES_NO = #{salesNo} AND SD.DIVISION_CODE = #{divisionCode} AND SD.COMPANY_CODE = #{companyCode} AND SD.PRODUCT_ASSETS_TYPE IN ('M', 'R', 'B')
AND SD.PRODUCT_CODE IN
#{productCode}

mapper.update:
MERGE INTO FCR_MST FM USING (SELECT FCM.FTA_CODE ,FCM.SALES_NO ,FCM.SALES_SEQ ,FCM.DIVISION_CODE ,FCM.COMPANY_CODE ,SUM(FCD.INAREA_AMOUNT) AS INAREA_AMOUNT ,SUM(FCD.OUTAREA_AMOUNT) AS OUTAREA_AMOUNT FROM FCR_MST FCM INNER JOIN FCR_DTL FCD ON FCM.FTA_CODE = FCD.FTA_CODE AND FCM.SALES_NO = FCD.SALES_NO AND FCM.SALES_SEQ = FCD.SALES_SEQ AND FCM.DIVISION_CODE = FCD.DIVISION_CODE AND FCM.COMPANY_CODE = FCD.COMPANY_CODE WHERE FCM.SALES_NO = #{salesNo} AND FCM.DIVISION_CODE = #{divisionCode} AND FCM.COMPANY_CODE = #{companyCode}
AND FCM.PRODUCT_CODE IN
#{productCode}
GROUP BY FCM.FTA_CODE, FCM.SALES_NO, FCM.SALES_SEQ, FCM.DIVISION_CODE, FCM.COMPANY_CODE) FMD ON (FM.FTA_CODE = FMD.FTA_CODE AND FM.SALES_NO = FMD.SALES_NO AND FM.SALES_SEQ = FMD.SALES_SEQ AND FM.DIVISION_CODE = FMD.DIVISION_CODE AND FM.COMPANY_CODE = FMD.COMPANY_CODE) WHEN MATCHED THEN UPDATE SET INAREA_AMOUNT = FMD.INAREA_AMOUNT ,OUTAREA_AMOUNT = FMD.OUTAREA_AMOUNT
